#include <cassert>
#include <cmath>
#include <cstdint>
#include <cstring>
#include <fstream>
#include <iomanip>
#include <iostream>
#include <string>
#include <vector>
#include "moe_accumulator/q1_moe_hawkeye_bf16_accumulator.h"

std::vector<uint16_t> read(const std::string &path, size_t elements) {
    std::ifstream file(path, std::ios::binary);
    std::vector<uint16_t> values(elements);
    file.read(reinterpret_cast<char *>(values.data()), elements * 2);
    assert(file.gcount() == static_cast<std::streamsize>(elements * 2));
    char extra; assert(!file.read(&extra, 1));
    return values;
}
float value(uint16_t v) {
    uint32_t bits = uint32_t(v) << 16; float result;
    std::memcpy(&result, &bits, 4); return result;
}
uint16_t bf16(float v) {
    uint32_t bits; std::memcpy(&bits, &v, 4);
    return uint16_t((bits + 0x7fff + ((bits >> 16) & 1)) >> 16);
}
int main(int argc, char **argv) {
    assert(argc == 4);
    auto inputs = read(argv[1], 3 * 4096), weights = read(argv[2], 2048 * 4096);
    auto expected = read(argv[3], 3 * 2048);
    unsigned differences26 = 0, differences25 = 0, differences64 = 0;
    std::cout << std::setprecision(17) << "{\"diagnostic_only\":true,\"rows\":[";
    for (unsigned row = 0; row < 3; ++row) {
        unsigned bad26 = 0, bad25 = 0, bad64 = 0;
        for (unsigned feature = 0; feature < 2048; ++feature) {
            const uint16_t *a = inputs.data() + row * 4096, *b = weights.data() + feature * 4096;
            float group26 = qrt_q1_moe_hawkeye::dot_bf16_hopper(a, b, 4096);
            float group25 = qrt_q1_moe_hawkeye::dot_bf16_ampere_lovelace(a, b, 4096);
            double exact = 0, absolute = 0, a_square = 0, b_square = 0;
            float sequential = 0;
            for (unsigned k = 0; k < 4096; ++k) {
                double product = double(value(a[k])) * value(b[k]);
                exact += product; absolute += std::fabs(product);
                a_square += double(value(a[k])) * value(a[k]);
                b_square += double(value(b[k])) * value(b[k]);
                sequential = std::fma(value(a[k]), value(b[k]), sequential);
            }
            const uint16_t reference = expected[row * 2048 + feature];
            bad26 += bf16(group26) != reference; bad25 += bf16(group25) != reference;
            bad64 += bf16(float(exact)) != reference;
            if (row == 1 && feature == 1875) {
                std::cerr << std::setprecision(17)
                    << "{\"position\":18554,\"feature\":1875,\"reference\":" << value(reference)
                    << ",\"group16_width26\":" << group26
                    << ",\"group16_width26_bf16\":" << value(bf16(group26))
                    << ",\"group8_width25\":" << group25
                    << ",\"float64_sum\":" << exact << ",\"sequential_fma\":" << sequential
                    << ",\"absolute_sum\":" << absolute
                    << ",\"l2_product\":" << std::sqrt(a_square * b_square) << "}\n";
            }
        }
        if (row) std::cout << ',';
        std::cout << "{\"position\":" << 18553 + row << ",\"elements\":2048,\"group16_width26_mismatches\":"
                  << bad26 << ",\"group8_width25_mismatches\":" << bad25
                  << ",\"float64_mismatches\":" << bad64 << '}';
        differences26 += bad26; differences25 += bad25; differences64 += bad64;
    }
    std::cout << "],\"total_group16_width26_mismatches\":" << differences26
              << ",\"total_group8_width25_mismatches\":" << differences25
              << ",\"total_float64_mismatches\":" << differences64 << "}\n";
}

