#include "native/providers/moe_accumulator/sm121_subgroup.h"
#include <cstdio>
#include <fstream>
#include <stdexcept>
#include <string>
#include <vector>

void check(hipError_t e) { if (e != hipSuccess) throw std::runtime_error(hipGetErrorString(e)); }
uint32_t bits(float x) { uint32_t b; std::memcpy(&b, &x, 4); return b; }
uint16_t bf16(float x) { uint32_t b = bits(x); return uint16_t((b+0x7fff+((b>>16)&1))>>16); }
std::vector<uint16_t> read(const char *path, size_t count) {
    std::ifstream f(path, std::ios::binary);
    std::vector<uint16_t> v(count); f.read(reinterpret_cast<char *>(v.data()), count*2);
    if (f.gcount() != std::streamsize(count*2)) throw std::runtime_error("input length");
    char extra; if (f.read(&extra, 1)) throw std::runtime_error("input tail");
    return v;
}
template<unsigned Lanes>
__global__ void replay(const uint16_t *inputs, const uint16_t *weights, float *out) {
    unsigned cell = (blockIdx.x * blockDim.x + threadIdx.x) / Lanes;
    if (cell >= 3*2048) return;
    float v;
    if constexpr (Lanes == 1)
        v = qrt_q1_moe_hawkeye::dot_bf16_hopper(inputs + (cell/2048)*4096,
                                               weights + (cell%2048)*4096, 4096);
    else v = qrt_sm121_subgroup::dot<Lanes>(inputs + (cell/2048)*4096,
                                           weights + (cell%2048)*4096, 4096);
    if ((threadIdx.x & (Lanes-1)) == 0) out[cell] = v;
}
int main(int argc, char **argv) try {
    if (argc != 4) throw std::runtime_error("inputs weights expected required");
    hipDeviceProp_t prop{}; check(hipGetDeviceProperties(&prop, 0));
    if (std::strncmp(prop.gcnArchName, "gfx1151", 7)) throw std::runtime_error("requires gfx1151");
    auto inputs = read(argv[1], 3*4096), weights = read(argv[2], 2048*4096);
    auto expected = read(argv[3], 3*2048);
    uint16_t *dx = nullptr, *dw = nullptr; float *dy = nullptr;
    check(hipMalloc(reinterpret_cast<void **>(&dx), inputs.size()*2));
    check(hipMalloc(reinterpret_cast<void **>(&dw), weights.size()*2));
    check(hipMalloc(reinterpret_cast<void **>(&dy), (3*2048+128)*4));
    check(hipMemcpy(dx, inputs.data(), inputs.size()*2, hipMemcpyHostToDevice));
    check(hipMemcpy(dw, weights.data(), weights.size()*2, hipMemcpyHostToDevice));
    std::vector<float> scalar, previous, result(3*2048+128, 12345.0f);
    unsigned all_bad = 0;
    for (unsigned lanes : {1u, 4u, 8u, 16u}) for (unsigned repetition = 0; repetition < 2; ++repetition) {
        std::fill(result.begin(), result.end(), 12345.0f);
        check(hipMemcpy(dy, result.data(), result.size()*4, hipMemcpyHostToDevice));
        dim3 grid((3*2048*lanes+255)/256);
        if (lanes == 1) hipLaunchKernelGGL(replay<1>, grid, dim3(256), 0, nullptr, dx, dw, dy);
        else if (lanes == 4) hipLaunchKernelGGL(replay<4>, grid, dim3(256), 0, nullptr, dx, dw, dy);
        else if (lanes == 8) hipLaunchKernelGGL(replay<8>, grid, dim3(256), 0, nullptr, dx, dw, dy);
        else hipLaunchKernelGGL(replay<16>, grid, dim3(256), 0, nullptr, dx, dw, dy);
        check(hipGetLastError()); check(hipDeviceSynchronize());
        check(hipMemcpy(result.data(), dy, result.size()*4, hipMemcpyDeviceToHost));
        if (lanes == 1 && repetition == 0) scalar = result;
        unsigned bad = 0, raw_bad = 0;
        for (unsigned i = 0; i < 3*2048; ++i) {
            bad += bf16(result[i]) != expected[i]; raw_bad += bits(result[i]) != bits(scalar[i]);
        }
        for (unsigned i = 3*2048; i < result.size(); ++i)
            if (result[i] != 12345.0f) throw std::runtime_error("output redzone");
        if (repetition && std::memcmp(previous.data(), result.data(), result.size()*4))
            throw std::runtime_error("repeat differs");
        previous = result;
        std::printf("{\"kind\":\"original_projection_rows\",\"lanes\":%u,\"repetition\":%u,\"elements\":6144,\"bf16_mismatches\":%u,\"scalar_raw_bit_mismatches\":%u,\"row1_feature1875\":%.17g,\"row1_feature1875_bits\":%u,\"inference_acceptance\":false}\n",
                    lanes, repetition, bad, raw_bad, result[2048+1875], bits(result[2048+1875]));
        all_bad += bad + raw_bad;
    }
    std::vector<uint16_t> after(weights.size());
    check(hipMemcpy(after.data(), dw, after.size()*2, hipMemcpyDeviceToHost));
    if (after != weights) throw std::runtime_error("weights mutated");
    after.resize(inputs.size()); check(hipMemcpy(after.data(), dx, after.size()*2, hipMemcpyDeviceToHost));
    if (after != inputs) throw std::runtime_error("inputs mutated");
    check(hipFree(dy)); check(hipFree(dw)); check(hipFree(dx));
    return all_bad ? 6 : 0;
} catch (const std::exception &e) { std::fprintf(stderr, "%s\n", e.what()); return 2; }

